// Tasks to build and serve the Playwright end-to-end test app in test/e2e/app.

import { deleteSync } from "del";
import fs from "fs-extra";
import gulp from "gulp";
import path from "path";
import paths from "../paths.cjs";

import "./gen-icons-json.js";
import "./locale-data.js";
import "./rspack.js";
import "./translations.js";

const upstreamBuild = (...parts) => path.resolve(paths.upstream_build_dir, ...parts);

gulp.task("clean-e2e-test-app", async () => deleteSync([paths.e2e_test_app_output_root]));

// Assets the fake hass fetches from /static/ at runtime, generated by the preparation tasks.
gulp.task("copy-static-e2e-test-app", async () => {
  const staticDir = paths.e2e_test_app_output_static;
  fs.copySync(upstreamBuild("translations/output"), path.join(staticDir, "translations"));
  fs.copySync(upstreamBuild("locale-data"), path.join(staticDir, "locale-data"));
  fs.copySync(upstreamBuild("mdi"), path.join(staticDir, "mdi"));
  fs.copySync(
    path.resolve(paths.root_dir, "node_modules/roboto-fontface/fonts/roboto"),
    path.join(staticDir, "fonts/roboto"),
    { filter: (src) => fs.statSync(src).isDirectory() || src.endsWith(".woff2") },
  );
});

const writeIndex = (entrypoint) => {
  const template = fs.readFileSync(
    path.resolve(paths.e2e_test_app_dir, "html/index.html.template"),
    "utf-8",
  );
  fs.outputFileSync(
    path.resolve(paths.e2e_test_app_output_root, "index.html"),
    template.replace("{{ entrypoint }}", entrypoint),
  );
};

gulp.task("gen-index-e2e-test-app-dev", async () =>
  writeIndex("/frontend_latest/entrypoint.dev.js"),
);

gulp.task("gen-index-e2e-test-app-prod", async () => {
  const manifest = fs.readJsonSync(path.resolve(paths.e2e_test_app_output_latest, "manifest.json"));
  writeIndex(manifest["entrypoint.js"]);
});

gulp.task(
  "build-e2e-test-app",
  gulp.series(
    async () => {
      process.env.NODE_ENV = "production";
    },
    "clean-e2e-test-app",
    "gen-icons-json",
    "build-translations",
    "build-locale-data",
    "rspack-prod-e2e-test-app",
    "copy-static-e2e-test-app",
    "gen-index-e2e-test-app-prod",
  ),
);

// Target name used by CI, as upstream does. Identical today because the harness is always built
// modern-only; it gives a CI-specific variant a home without renaming the workflow step.
gulp.task("build-e2e-test-app-e2e", gulp.series("build-e2e-test-app"));

gulp.task(
  "develop-e2e-test-app",
  gulp.series(
    async () => {
      process.env.NODE_ENV = "development";
    },
    "clean-e2e-test-app",
    "gen-icons-json",
    "build-translations",
    "build-locale-data",
    "copy-static-e2e-test-app",
    "gen-index-e2e-test-app-dev",
    "rspack-dev-server-e2e-test-app",
  ),
);
